```python
"""Load a JSON config from disk, falling back to built-in defaults.

Precedence, lowest to highest: DEFAULTS, the JSON file, the environment.
"""

from __future__ import annotations

import copy
import json
import logging
import os
from pathlib import Path
from typing import Any

log = logging.getLogger(__name__)

MIN_PORT = 1024
MAX_PORT = 65535
ENV_PREFIX = "APP_"
NESTED_SEP = "__"

DEFAULTS: dict[str, Any] = {
    "host": "127.0.0.1",
    "port": 8080,
    "debug": False,
    "log_level": "INFO",
    "retries": 3,
}

_TRUE = {"1", "true", "yes", "on"}
_FALSE = {"0", "false", "no", "off"}


class ConfigError(Exception):
    """Raised when a config file or environment override cannot be used."""


def _merge(base: dict[str, Any], override: dict[str, Any]) -> dict[str, Any]:
    """Recursively overlay `override` onto a copy of `base`."""
    result = copy.deepcopy(base)
    for key, value in override.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = _merge(result[key], value)
        else:
            result[key] = value
    return result


def _coerce(raw: str, current: Any, name: str) -> Any:
    """Convert an env string to the type of the value it is replacing.

    With no existing value to match, the string is parsed as JSON if it
    can be and left as a string otherwise.
    """
    if isinstance(current, bool):
        low = raw.strip().lower()
        if low in _TRUE:
            return True
        if low in _FALSE:
            return False
        raise ConfigError(f"{name}: expected a boolean, got {raw!r}")
    if isinstance(current, int):
        try:
            return int(raw)
        except ValueError:
            raise ConfigError(f"{name}: expected an integer, got {raw!r}") from None
    if isinstance(current, float):
        try:
            return float(raw)
        except ValueError:
            raise ConfigError(f"{name}: expected a number, got {raw!r}") from None
    if isinstance(current, (list, dict)):
        try:
            return json.loads(raw)
        except json.JSONDecodeError as exc:
            raise ConfigError(f"{name}: expected JSON, got {raw!r} ({exc})") from None
    if isinstance(current, str):
        return raw
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        return raw


def _apply_env(
    config: dict[str, Any],
    prefix: str = ENV_PREFIX,
    environ: dict[str, str] | None = None,
) -> dict[str, Any]:
    """Overlay `PREFIX_KEY` environment variables onto `config` in place.

    `APP_PORT=9000` sets `port`; `APP_DB__HOST` sets `db.host`. Values are
    coerced to the type of the entry they replace, so `APP_DEBUG=true`
    becomes a bool rather than the string "true". A variable that names an
    unknown key still applies -- it is an explicit instruction, not noise.
    """
    environ = os.environ if environ is None else environ
    for var, raw in sorted(environ.items()):
        if not var.startswith(prefix) or var == prefix:
            continue
        path = [part.lower() for part in var[len(prefix):].split(NESTED_SEP)]
        if any(not part for part in path):
            log.warning("ignoring malformed environment override %s", var)
            continue
        target = config
        for part in path[:-1]:
            nxt = target.get(part)
            if not isinstance(nxt, dict):
                nxt = {}
                target[part] = nxt
            target = nxt
        leaf = path[-1]
        target[leaf] = _coerce(raw, target.get(leaf), var)
        log.debug("config %s overridden by %s", ".".join(path), var)
    return config


def _validate_port(config: dict[str, Any], source: str) -> None:
    """Check that `port`, if present, is an int in the unprivileged range."""
    if "port" not in config:
        return
    port = config["port"]
    # bool is a subclass of int, but True is not a port number.
    if isinstance(port, bool) or not isinstance(port, int):
        raise ConfigError(f"{source}: port must be an integer, got {type(port).__name__}")
    if not MIN_PORT <= port <= MAX_PORT:
        raise ConfigError(f"{source}: port {port} outside {MIN_PORT}-{MAX_PORT}")


def load_config(
    path: str | Path,
    defaults: dict[str, Any] | None = None,
    env_prefix: str = ENV_PREFIX,
    environ: dict[str, str] | None = None,
) -> dict[str, Any]:
    """Return the config at `path` merged over `defaults`, then over the env.

    A missing file is not an error: the defaults are used. A file that
    exists but does not parse as a JSON object is reported at WARNING level
    and the defaults are used, so a corrupted file degrades to a working
    process rather than a crash. A file that cannot be read at all, or a
    value that fails validation, still raises ConfigError.

    Pass `env_prefix=""` with a caller-supplied `environ` to consume a bare
    mapping, or an explicit `environ` in tests to avoid touching os.environ.
    """
    defaults = DEFAULTS if defaults is None else defaults
    path = Path(path)
    source = str(path)

    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        log.info("config file %s not found; using defaults", path)
        merged, source = copy.deepcopy(defaults), "defaults"
    except OSError as exc:
        raise ConfigError(f"could not read {path}: {exc}") from exc
    else:
        try:
            loaded = json.loads(text)
        except json.JSONDecodeError as exc:
            log.warning("invalid JSON in %s (%s); falling back to defaults", path, exc)
            loaded = None
        if isinstance(loaded, dict):
            merged = _merge(defaults, loaded)
        else:
            if loaded is not None:
                log.warning(
                    "%s must contain a JSON object, got %s; falling back to defaults",
                    path,
                    type(loaded).__name__,
                )
            merged, source = copy.deepcopy(defaults), "defaults"

    merged = _apply_env(merged, env_prefix, environ)
    _validate_port(merged, source)
    return merged
```

Two notes on the env layer, since it changes the failure story:

- A bad env value raises `ConfigError` rather than warning and falling back. `APP_PORT=nope` is someone typing an instruction, so ignoring it would boot on 8080 while the operator believes otherwise — the same reasoning behind leaving `_validate_port` strict. Only the *file* gets the lenient treatment, because unparseable bytes carry no intent.
- Env vars naming keys absent from the defaults are applied, not rejected. That makes typos (`APP_PROT=9000`) silently create a `prot` key. If you'd rather have unknown keys be an error, the check is one line at the leaf assignment in `_apply_env` — say the word and I'll add it, though it does mean callers can no longer introduce config keys without touching `DEFAULTS`.
